import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
aoi = ee.Geometry.Point([-91.35, 0.02]).buffer(5000)  # Wolf Volcano, ~5 km radius
scale = 1000
band_name = 'Gap_Filled_DNB_BRDF-Corrected_NTL'
dates = {'Jan06': '2022-01-06', 'Jan07': '2022-01-07'}

def get_day_stats(date_str, label):
    start = ee.Date(date_str)
    end = start.advance(1, 'day')
    col = ee.ImageCollection('NOAA/VIIRS/001/VNP46A1').filterBounds(aoi).filterDate(start, end)
    size = col.size().getInfo()
    print(f"{label} Images: {size}")
    if size == 0:
        return {'status': 'C1'}
    img = col.mosaic()
    # Select gap-filled NTL band and mask invalid (<0) values
    band = img.select(band_name)
    band = band.updateMask(band.gte(0))
    # Pixel counts
    total_px = ee.Image(1).rename('ones').reduceRegion(
        reducer=ee.Reducer.count(), geometry=aoi, scale=scale, maxPixels=1e9
    ).get('ones').getInfo()
    valid_px = band.reduceRegion(
        reducer=ee.Reducer.count(), geometry=aoi, scale=scale, maxPixels=1e9
    ).get(band_name).getInfo()
    if total_px is None or total_px == 0:
        return {'status': 'C2'}
    if valid_px is None or valid_px == 0:
        print(f"{label} Valid px: 0 / Total: {total_px} (Cloud/Masked: 100.0%)")
        return {'status': 'C2'}
    cloud_pct = 100.0 * (1.0 - float(valid_px) / float(total_px))
    # Mean brightness
    mean_val = band.reduceRegion(
        reducer=ee.Reducer.mean(), geometry=aoi, scale=scale, maxPixels=1e9
    ).get(band_name).getInfo()
    if mean_val is None or (isinstance(mean_val, float) and (math.isnan(mean_val) or math.isinf(mean_val))):
        return {'status': 'C3'}
    print(f"{label} Valid px: {valid_px} / Total: {total_px} (Cloud/Masked: {cloud_pct:.1f}%)")
    print(f"{label} Mean NTL: {mean_val:.3f}")
    return {'status': 'OK', 'mean': float(mean_val)}

try:
    s6 = get_day_stats(dates['Jan06'], 'Jan06')
    if s6.get('status') != 'OK':
        print(s6['status'])
        sys.exit(0)
    s7 = get_day_stats(dates['Jan07'], 'Jan07')
    if s7.get('status') != 'OK':
        print(s7['status'])
        sys.exit(0)

    # Compare: Was Jan 7 brighter than Jan 6?
    if s7['mean'] > s6['mean']:
        print("A")
    else:
        print("B")

except Exception as e:
    # Minimal diagnostic to stay within 20 lines
    print("D")
